/* @autogenerated */
import { roleProjectionToValue } from './role.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('roleProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    name: 'value-name',
    resourceServer: { $ref: 'ref-resourceServer' },
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(roleProjectionToValue(null)).toBeNull();
    expect(roleProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(roleProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      name: 'value-name',
      resourceServer: () => ({ uid: 'ref-resourceServer' }),
      version: 'value-version',
    } as any;
    expect(roleProjectionToValue(projection)).toEqual(value);
  });
});
